export interface ProtocolValidationError { path: string; message: string }
export interface ProtocolValidationResult { ok: boolean; errors: ProtocolValidationError[] }

function matchesType(value: unknown, type: string): boolean {
  if (type === "null") return value === null;
  if (type === "array") return Array.isArray(value);
  if (type === "integer") return typeof value === "number" && Number.isSafeInteger(value);
  if (type === "number") return typeof value === "number" && Number.isFinite(value);
  if (type === "object") return value !== null && typeof value === "object" && !Array.isArray(value);
  return typeof value === type;
}

function validateNode(value: unknown, node: any, path: string, errors: ProtocolValidationError[], root: any): boolean {
  const start = errors.length;
  if (node.$ref) {
    const target = node.$ref.split("/").slice(1).reduce((current: any, part: string) => current?.[part.replaceAll("~1", "/").replaceAll("~0", "~")], root);
    if (!target) errors.push({ path, message: `unresolved schema reference ${node.$ref}` });
    else validateNode(value, target, path, errors, root);
    return errors.length === start;
  }
  if (Object.prototype.hasOwnProperty.call(node, "const") && JSON.stringify(value) !== JSON.stringify(node.const)) {
    errors.push({ path, message: `must equal ${JSON.stringify(node.const)}` });
  }
  if (node.enum && !node.enum.some((candidate: unknown) => JSON.stringify(candidate) === JSON.stringify(value))) {
    errors.push({ path, message: "must be an allowed enum value" });
  }
  for (const keyword of ["allOf"] as const) for (const child of node[keyword] || []) validateNode(value, child, path, errors, root);
  for (const keyword of ["oneOf", "anyOf"] as const) {
    if (!node[keyword]) continue;
    const matches = node[keyword].filter((child: any) => {
      const branchErrors: ProtocolValidationError[] = [];
      validateNode(value, child, path, branchErrors, root);
      return branchErrors.length === 0;
    }).length;
    if ((keyword === "oneOf" && matches !== 1) || (keyword === "anyOf" && matches < 1)) errors.push({ path, message: `must match ${keyword}` });
  }
  const types = Array.isArray(node.type) ? node.type : node.type ? [node.type] : [];
  if (types.length && !types.some((type: string) => matchesType(value, type))) {
    errors.push({ path, message: `must be ${types.join(" or ")}` });
    return false;
  }
  if (typeof value === "string") {
    if (node.minLength != null && value.length < node.minLength) errors.push({ path, message: `must have length >= ${node.minLength}` });
    if (node.maxLength != null && value.length > node.maxLength) errors.push({ path, message: `must have length <= ${node.maxLength}` });
    if (node.pattern && !new RegExp(node.pattern, "u").test(value)) errors.push({ path, message: "must match pattern" });
    if (node.format === "date-time" && Number.isNaN(Date.parse(value))) errors.push({ path, message: "must be an ISO date-time" });
  }
  if (typeof value === "number") {
    if (node.minimum != null && value < node.minimum) errors.push({ path, message: `must be >= ${node.minimum}` });
    if (node.maximum != null && value > node.maximum) errors.push({ path, message: `must be <= ${node.maximum}` });
  }
  if (Array.isArray(value)) {
    if (node.minItems != null && value.length < node.minItems) errors.push({ path, message: `must contain >= ${node.minItems} items` });
    if (node.maxItems != null && value.length > node.maxItems) errors.push({ path, message: `must contain <= ${node.maxItems} items` });
    if (node.uniqueItems && new Set(value.map((item) => JSON.stringify(item))).size !== value.length) errors.push({ path, message: "must contain unique items" });
    value.forEach((item, index) => validateNode(item, node.items || {}, `${path}/${index}`, errors, root));
  }
  if (value && typeof value === "object" && !Array.isArray(value)) {
    const record = value as Record<string, unknown>;
    for (const name of node.required || []) if (!Object.prototype.hasOwnProperty.call(record, name)) errors.push({ path: `${path}/${name}`, message: "is required" });
    for (const [name, child] of Object.entries(node.properties || {})) if (Object.prototype.hasOwnProperty.call(record, name)) validateNode(record[name], child, `${path}/${name}`, errors, root);
    const known = new Set(Object.keys(node.properties || {}));
    for (const [name, childValue] of Object.entries(record)) {
      if (known.has(name)) continue;
      if (node.additionalProperties === false) errors.push({ path: `${path}/${name}`, message: "additional property is not allowed" });
      else if (node.additionalProperties && typeof node.additionalProperties === "object") validateNode(childValue, node.additionalProperties, `${path}/${name}`, errors, root);
    }
  }
  return errors.length === start;
}

export function validateProtocolMessage(value: unknown): ProtocolValidationResult {
  const errors: ProtocolValidationError[] = [];
  validateNode(value, CC_AGENT_PROTOCOL_SCHEMA, "#", errors, CC_AGENT_PROTOCOL_SCHEMA);
  return { ok: errors.length === 0, errors };
}

export function assertProtocolMessage(value: unknown): asserts value is ClientRequest | ClientResponse | ServerRequest | ServerNotification {
  const result = validateProtocolMessage(value);
  if (!result.ok) throw new TypeError(`Invalid CC Agent protocol message: ${result.errors.map((error) => `${error.path} ${error.message}`).join("; ")}`);
}

export type Identifier = string;

export type Digest = string;

export type Timestamp = string;

export type JsonValue = null | boolean | number | string | Array<JsonValue> | { [key: string]: JsonValue; };

export type DataPolicy = { "origin": string; "trust": "trusted_host" | "authenticated_user" | "untrusted_content" | "unknown"; "sensitivity": "public" | "internal" | "confidential" | "secret"; "allowedSinks": Array<string>; "declassificationDecisionId"?: Identifier; };

export type Thread = { "id": Identifier; "status": "active" | "idle" | "archived"; "title"?: string | null; "parentThreadId"?: Identifier | null; "createdAt": Timestamp; "updatedAt": Timestamp; "revision": number; "metadata"?: { [key: string]: JsonValue; }; };

export type Turn = { "id": Identifier; "threadId": Identifier; "status": "queued" | "running" | "waiting_approval" | "waiting_input" | "completed" | "failed" | "interrupted"; "createdAt": Timestamp; "completedAt"?: Timestamp | null; "revision": number; "terminalEvidence"?: TerminalEvidence | null; };

export type Item = { "id": Identifier; "threadId": Identifier; "turnId": Identifier; "parentId"?: Identifier | null; "kind": "user_message" | "assistant_message" | "reasoning" | "tool" | "approval" | "plan" | "subagent" | "artifact" | "error"; "status": "started" | "streaming" | "completed" | "failed" | "cancelled"; "content"?: JsonValue; "dataPolicy"?: DataPolicy; "createdAt": Timestamp; "completedAt"?: Timestamp | null; };

export type PermissionGrant = { "capability": string; "scope": string; "expiresAt"?: Timestamp | null; };

export type ApprovalBinding = { "threadId": Identifier; "turnId": Identifier; "itemId": Identifier; "attemptId"?: Identifier | null; "operationDigest": Digest; "policyDigest": Digest; "workspaceDigest"?: Digest | null; "cwd"?: string; "nonce": Identifier; "expiresAt": Timestamp; };

export type ApprovalDecision = { "kind": "acceptOnce"; } | { "kind": "acceptForTurn" | "acceptForSession"; "permissions"?: Array<PermissionGrant>; } | { "kind": "decline" | "cancel"; "reason"?: string; };

export type ApprovalRequest = { "id": Identifier; "binding": ApprovalBinding; "operation": JsonValue; "risk": "low" | "medium" | "high" | "critical"; "reason": string; "requestedPermissions"?: Array<PermissionGrant>; };

export type TerminalEvidence = { "status": "succeeded" | "failed" | "partial" | "cancelled" | "blocked" | "budget_exhausted"; "eventDigest": Digest; "outputDigest"?: Digest | null; "artifactIds"?: Array<Identifier>; "commit"?: string | null; "testReceiptIds"?: Array<Identifier>; };

export type TypedPort = { "name": Identifier; "schema": { [key: string]: JsonValue; }; "required"?: boolean; "dataPolicy"?: DataPolicy; };

export type Budget = { "turns"?: number; "tokens"?: number; "costUsd"?: number; "wallMs"?: number; "spawnCount"?: number; };

export type TaskNode = { "id": Identifier; "kind": "task" | "join" | "human" | "subgraph"; "dependsOn": Array<Identifier>; "inputs": Array<TypedPort>; "outputs": Array<TypedPort>; "inputBindings"?: { [key: string]: string; }; "capabilities"?: Array<string>; "tools"?: Array<string>; "skills"?: Array<string>; "budget"?: Budget; "writeSet"?: Array<string>; "workspaceIsolation"?: "worktree" | "declared_scope"; "effectClass": "none" | "read" | "workspace_write" | "external"; "idempotencyKey"?: string; "compensationNodeId"?: Identifier; "priority"?: number; "join"?: "all" | "any" | "quorum" | "race"; "quorum"?: number; "retryLimit"?: number; };

export type Edge = { "id": Identifier; "from": Identifier; "to": Identifier; "kind": "control" | "data" | "message" | "review" | "merge" | "compensation"; "when": "success" | "failure" | "always" | "timeout" | "cancel"; "fromPort"?: Identifier; "toPort"?: Identifier; };

export type LoopRegion = { "id": Identifier; "entryNodeId": Identifier; "exitNodeId": Identifier; "nodeIds": Array<Identifier>; "maxIterations": number; "condition"?: string; "budget"?: Budget; };

export type TriggerBinding = { "id": Identifier; "kind": "manual" | "schedule" | "webhook" | "message" | "child_completion"; "targetNodeId": Identifier; "sourceRef"?: string | null; "authorityDigest": Digest; "dataPolicy"?: DataPolicy; };

export type Region = { "id": Identifier; "kind": "sequence" | "parallel" | "condition" | "try" | "compensation"; "nodeIds": Array<Identifier>; "parentRegionId"?: Identifier | null; "entryNodeId"?: Identifier; "exitNodeId"?: Identifier; };

export type SubgraphCall = { "nodeId": Identifier; "definitionId": Identifier; "revisionDigest": Digest; "maxDepth": number; "inputBindings"?: Array<SubgraphPortBinding>; "outputBindings"?: Array<SubgraphPortBinding>; "budget"?: Budget; };

export type SubgraphPortBinding = { "parentPort": Identifier; "childNodeId": Identifier; "childPort": Identifier; };

export type GraphDefinition = { "schemaVersion": number; "id": Identifier; "revision": number; "triggers"?: Array<TriggerBinding>; "regions"?: Array<Region>; "nodes": Array<TaskNode>; "edges": Array<Edge>; "loops": Array<LoopRegion>; "subgraphCalls": Array<SubgraphCall>; "budget": Budget; "allowedCapabilities"?: Array<string>; "metadata"?: { [key: string]: JsonValue; }; };

export type GraphRevision = { "definitionId": Identifier; "revision": number; "revisionDigest": Digest; "schemaVersion": number; "parentRevisionDigest"?: Digest | null; "createdAt": Timestamp; "producerLeaseId"?: Identifier | null; };

export type IterationFrame = { "id": Identifier; "runId": Identifier; "regionId": Identifier; "parentFrameId"?: Identifier | null; "iterationPath": Array<number>; "status": "active" | "succeeded" | "failed" | "cancelled" | "exhausted"; "startedAt"?: Timestamp; "completedAt"?: Timestamp | null; };

export type NodeAttempt = { "id": Identifier; "runId": Identifier; "nodeId": Identifier; "iterationPath": Array<number>; "attempt": number; "status": "pending" | "running" | "succeeded" | "failed" | "cancelled" | "timed_out" | "reconciliation_required"; "acceptedAssignmentAttemptId"?: Identifier | null; "createdAt": Timestamp; "completedAt"?: Timestamp | null; "terminalEvidence"?: TerminalEvidence | null; };

export type AssignmentAttempt = { "id": Identifier; "runId": Identifier; "nodeId": Identifier; "agentId": Identifier; "role": "lead" | "executor" | "reviewer" | "judge" | "observer"; "leaseId": Identifier; "fence": number; "status": "offered" | "active" | "accepted" | "rejected" | "expired" | "cancelled"; "createdAt": Timestamp; "expiresAt"?: Timestamp; };

export type ArtifactRef = { "id": Identifier; "digest": Digest; "producerNodeId": Identifier; "producerAttemptId": Identifier; "producerLeaseId": Identifier; "schema": { [key: string]: JsonValue; }; "commit"?: string | null; "validationEvidence"?: Array<Identifier>; "consumerNodeIds"?: Array<Identifier>; "dataPolicy": DataPolicy; };

export type EffectReceipt = { "receiptDigest": Digest; "externalId"?: string | null; "recordedAt": Timestamp; "metadata"?: { [key: string]: JsonValue; }; };

export type Effect = { "id": Identifier; "runId": Identifier; "nodeId": Identifier; "attemptId": Identifier; "idempotencyKey": string; "baseIdempotencyKey"?: string; "iterationPath"?: Array<number>; "operationDigest": Digest; "status": "started" | "committed" | "failed" | "unknown" | "compensated"; "receipt"?: EffectReceipt | null; "compensationEffectId"?: Identifier | null; "createdAt": Timestamp; "updatedAt"?: Timestamp; };

export type Message = { "id": Identifier; "runId": Identifier; "fromAttemptId": Identifier; "toAgentId": Identifier; "causationId"?: Identifier | null; "correlationId"?: Identifier | null; "mode": "send" | "followup"; "status": "admitted" | "delivered" | "read" | "processed" | "dead_letter"; "payload": JsonValue; "payloadDigest": Digest; "dataPolicy": DataPolicy; "createdAt": Timestamp; "expiresAt"?: Timestamp; };

export type Handoff = { "id": Identifier; "runId": Identifier; "nodeId": Identifier; "fromAttemptId": Identifier; "toAgentId": Identifier; "revisionDigest": Digest; "authorityDigest": Digest; "artifactIds"?: Array<Identifier>; "status": "offered" | "accepted" | "rejected" | "committed" | "revoked" | "expired"; "expiresAt": Timestamp; };

export type HumanTask = { "id": Identifier; "runId": Identifier; "revisionDigest": Digest; "nodeId": Identifier; "attemptId": Identifier; "operationDigest": Digest; "status": "open" | "claimed" | "decided" | "cancelled" | "expired"; "claimActorId"?: Identifier | null; "claimLeaseId"?: Identifier | null; "nonce": Identifier; "expiresAt": Timestamp; "decision"?: ApprovalDecision | null; };

export type GraphRun = { "id": Identifier; "definitionId": Identifier; "revision": number; "revisionDigest": Digest; "occurrenceId"?: Identifier | null; "phase": "open" | "sealed"; "status": "running" | "waiting_input" | "waiting_external" | "waiting_human" | "reconciliation_required" | "succeeded" | "failed" | "partial" | "cancelled" | "blocked" | "deadlocked" | "budget_exhausted"; "graphRevision": number; "createdAt": Timestamp; "completedAt"?: Timestamp | null; };

export type InitializeParams = { "protocolVersion": number; "minimumProtocolVersion": number; "client": { "name": string; "version": string; }; "features"?: Array<string>; };

export type JsonRpcRequestBase = { "jsonrpc": "2.0"; "id": string | number; "method": string; "params"?: {  }; };

export type ClientRequest = (JsonRpcRequestBase) & ({ "method"?: "initialize"; "params"?: InitializeParams; } | { "method"?: "thread/start" | "thread/resume" | "thread/fork" | "thread/read" | "thread/list" | "thread/archive" | "turn/start" | "turn/interrupt"; });

export type ClientResponse = unknown | unknown;

export type ServerRequest = { "jsonrpc": "2.0"; "id": string | number; "method": "approval/decide" | "humanTask/decide"; "params": JsonValue; };

export type ServerNotification = { "jsonrpc": "2.0"; "method": "thread/updated" | "turn/started" | "turn/completed" | "item/started" | "item/delta" | "item/completed" | "approval/requested" | "approval/resolved" | "tool/requested" | "tool/result" | "subagent/started" | "subagent/completed" | "graph/event"; "params": JsonValue; };
